const LEVELS = ['sd', 'smp', 'sma', 'college'];
const DIFFICULTIES = ['easy', 'medium', 'hard', 'very_hard', 'bonus'];
const SUBJECTS = [
  'Matematika', 'Bahasa Indonesia', 'Bahasa Inggris', 'IPA', 'IPS', 'Sejarah',
  'Geografi', 'PPKn', 'Ekonomi', 'Pendidikan Agama Islam', 'Pengetahuan Umum',
];

function stableShuffle(values, seedText) {
  const result = [...values];
  let seed = 2166136261;
  for (const char of seedText) seed = Math.imul(seed ^ char.charCodeAt(0), 16777619) >>> 0;
  for (let i = result.length - 1; i > 0; i -= 1) {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    const j = seed % (i + 1);
    [result[i], result[j]] = [result[j], result[i]];
  }
  return result;
}

const DISTRACTOR_STOP_WORDS = new Set((
  'yang dan atau dari untuk dalam dengan pada ketika jika maka adalah merupakan sebagai suatu sebuah secara dapat akan ke di oleh kepada terhadap karena agar bahwa ini itu tersebut setiap lebih sangat tidak hanya juga serta namun yakni yaitu bisa harus paling menjadi telah tentang antara beberapa lainnya masih sesuai melalui seluruh bagian proses contoh konsep tepat digunakan disebut dapatnya ' +
  'the a an is are of and or to in on by for with if then this that from as can may must be has have had than which while into over under their its some any all other most same'
).split(/\s+/));

function contentTokens(value) {
  return (String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().match(/[a-z0-9]+/g) || [])
    .filter((token) => token.length > 2 && !DISTRACTOR_STOP_WORDS.has(token) && !/^\d+$/.test(token));
}

function tokenSetSimilarity(a, b) {
  const left = new Set(contentTokens(a));
  const right = new Set(contentTokens(b));
  if (!left.size || !right.size) return 0;
  let intersection = 0;
  for (const token of left) if (right.has(token)) intersection += 1;
  return intersection / (left.size + right.size - intersection);
}

// Cari konsep yang paling dekat dalam mata pelajaran dan jenjang yang sama.
// Dengan begitu, opsi salah tetap berada dalam rumpun konsep yang relevan, bukan diacak dari topik jauh.
function rankRelatedRows(seed, rows, level) {
  const entries = rows.map((item) => Array.isArray(item) ? { row: item, level: null } : item);
  const docs = entries.map((item) => contentTokens(item.row.join(' ')));
  const documentFrequency = new Map();
  for (const doc of docs) {
    for (const token of new Set(doc)) documentFrequency.set(token, (documentFrequency.get(token) || 0) + 1);
  }
  const vectors = docs.map((doc) => {
    const counts = new Map();
    for (const token of doc) counts.set(token, (counts.get(token) || 0) + 1);
    const vector = new Map();
    for (const [token, count] of counts) {
      const idf = Math.log(1 + docs.length / (1 + (documentFrequency.get(token) || 0)));
      vector.set(token, (1 + Math.log(count)) * idf);
    }
    return vector;
  });
  function cosine(a, b) {
    let dot = 0, normA = 0, normB = 0;
    for (const value of a.values()) normA += value * value;
    for (const value of b.values()) normB += value * value;
    for (const [token, value] of a) dot += value * (b.get(token) || 0);
    return normA && normB ? dot / Math.sqrt(normA * normB) : 0;
  }
  const seedIndex = entries.findIndex((item) => item.row === seed);
  return entries.map((entry, index) => ({
    row: entry.row,
    level: entry.level,
    index,
    score: index === seedIndex ? -1 : (cosine(vectors[seedIndex], vectors[index]) * 0.78) + (tokenSetSimilarity(seed[0], entry.row[0]) * 0.18) + (entry.level === level ? 0.04 : 0),
    termSimilarity: index === seedIndex ? 1 : tokenSetSimilarity(seed[0], entry.row[0]),
  })).filter((item) => item.index !== seedIndex)
    .sort((a, b) => b.score - a.score || a.index - b.index);
}

function generatedQuestion(seed, subject, level, difficulty, index, relatedRows, q) {
  const [term, definition, application, reasoning, scenario, conclusion] = seed;
  const column = { easy: 0, medium: 2, hard: 3, very_hard: 5, bonus: 0 }[difficulty];
  let question;
  let correct;
  let explanation;
  if (difficulty === 'easy') {
    question = `Pengertian: “${definition}”. Istilah yang tepat adalah ...`;
    correct = term;
    explanation = `${term}: ${definition}.`;
  } else if (difficulty === 'medium') {
    question = `Manakah contoh atau penerapan yang tepat untuk konsep ${term}?`;
    correct = application;
    explanation = `Contoh yang sesuai: ${application}.`;
  } else if (difficulty === 'hard') {
    question = `Prinsip yang paling tepat untuk menjelaskan konsep ${term} adalah ...`;
    correct = reasoning;
    explanation = `${reasoning}.`;
  } else if (difficulty === 'bonus') {
    question = `Bonus Tantangan: ${scenario}. Konsep yang paling tepat menjelaskan kasus ini adalah ...`;
    correct = term;
    explanation = `Kasus ini menerapkan konsep ${term}. ${reasoning}.`;
  } else {
    question = `Analisis kasus: ${scenario}. Kesimpulan paling tepat adalah ...`;
    correct = conclusion;
    explanation = `Kesimpulan: ${conclusion}. Kasus ini berkaitan dengan ${term}.`;
  }

  const ranked = rankRelatedRows(seed, relatedRows, level);
  const distractors = [];
  const normalizedCorrect = String(correct).trim().toLocaleLowerCase('id-ID');
  // Istilah dengan kemiripan nama sangat tinggi dapat menjadi jawaban ganda; hindari bila ada alternatif lain.
  const acceptable = ranked.filter((item) => !(column === 0 && item.termSimilarity >= 0.62));
  const ordered = [...acceptable, ...ranked.filter((item) => !acceptable.includes(item))];
  for (const item of ordered) {
    const choice = item.row[column];
    if (!choice || String(choice).trim().toLocaleLowerCase('id-ID') === normalizedCorrect) continue;
    if (distractors.some((existing) => existing.trim().toLocaleLowerCase('id-ID') === choice.trim().toLocaleLowerCase('id-ID'))) continue;
    distractors.push(choice);
    if (distractors.length === 3) break;
  }
  const options = stableShuffle([correct, ...distractors], `${subject}|${level}|${difficulty}|options|${index}`);
  return q(subject, level, difficulty, question, options, options.indexOf(correct), explanation, { generated: true });
}

function expandQuestionBank({ q, existingQuestions }) {
  const supplemental = [];
  for (const subject of SUBJECTS) {
    for (const level of LEVELS) {
      const rows = SEEDS[`${subject}|${level}`];
      if (!Array.isArray(rows) || rows.length < 10) {
        throw new Error(`Bank seed ${subject}/${level} harus memiliki sedikitnya 10 konsep; ditemukan ${rows?.length || 0}`);
      }
      const relatedRows = LEVELS.flatMap((candidateLevel) =>
        (SEEDS[`${subject}|${candidateLevel}`] || []).map((row) => ({ row, level: candidateLevel }))
      );
      for (const difficulty of DIFFICULTIES) {
        const exactCount = existingQuestions.filter((item) => item.subject === subject && item.level === level && item.difficulty === difficulty).length;
        const needed = Math.max(0, 10 - exactCount);
        const seen = new Set(existingQuestions.filter((item) => item.subject === subject && item.level === level && item.difficulty === difficulty).map((item) => item.question));
        let added = 0;
        for (let index = 0; index < rows.length && added < needed; index += 1) {
          const item = generatedQuestion(rows[index], subject, level, difficulty, index, relatedRows, q);
          if (seen.has(item.question)) continue;
          seen.add(item.question);
          supplemental.push(item);
          added += 1;
        }
        if (added < needed) throw new Error(`Tidak cukup soal unik untuk ${subject}/${level}/${difficulty}: perlu ${needed}, tersedia ${added}`);
      }
    }
  }
  return supplemental;
}

module.exports = { expandQuestionBank, SEEDS, LEVELS, DIFFICULTIES, SUBJECTS };
